"""Regenera las páginas estáticas. Python 3, sin dependencias."""
from pathlib import Path
from html import escape
root = Path(__file__).parent / 'docs'
root.mkdir(exist_ok=True)
nav = [('soluciones.html','Soluciones'),('productos.html','Productos'),('proyectos.html','Proyectos'),('taller.html','El taller')]
image_sizes = {'bayahibe':(1050,1400), 'bayahibe-detalle':(1400,1050),
 'quiosco':(1050,1400), 'quiosco-proceso':(1050,1400), 'punta-cana':(1400,788),
 'oceanpark':(1400,788), 'numeracion':(1050,1400), 'direccion':(1050,1400),
 'pictograma':(1050,1400), 'laser':(1050,1400), 'letras-proceso':(1050,1400),
 'letras-pintura':(1600,1200), 'bandera-preparacion':(1200,1600)}
def image(name,alt,hero=False):
 width,height = image_sizes.get(name,(1200,900))
 return f'<img src="assets/{name}.webp" alt="{escape(alt,quote=True)}" width="{width}" height="{height}" '+('fetchpriority="high"' if hero else 'loading="lazy"')+' decoding="async">'
# Captions distinguish conceptual references from actual workshop photographs.
conceptual = {'hero', 'display', 'workshop'}
process_images = {'numeracion', 'direccion', 'pictograma', 'laser', 'letras-proceso', 'letras-pintura', 'bandera-preparacion', 'quiosco-proceso'}
def photo(name,alt,hero=False,caption=''):
 caption = caption or ('Imagen conceptual · Referencia de aplicación' if name in conceptual else 'Fotografía de producción · Pieza en proceso' if name in process_images else '')
 return '<figure>'+image(name,alt,hero)+(f'<figcaption>{escape(caption)}</figcaption>' if caption else '')+'</figure>'
def button(label,href='contacto.html',secondary=False):
 return f'<a class="button {"secondary" if secondary else ""}" href="{href}">{label}</a>'
def cta(title='Demos forma a lo que necesitas.', text='Cuéntanos tu idea y encontremos un punto de partida.', label='Solicitar cotización', href='contacto.html'):
 return f'<section class="contact-band wrap"><div><h2>{title}</h2><p>{text}</p></div>'+button(label,href)+'</section>'

def project_cta():
 return cta('¿Tienes un proyecto en mente?', 'Cuéntanos qué necesitas diseñar, fabricar o instalar. Una referencia, unas medidas o una idea son un buen comienzo.', href='contacto.html?origen=proyectos')

def workshop_cta():
 return cta('De una idea podemos empezar.', 'Si tienes una referencia, unas medidas o una necesidad concreta, podemos evaluar cómo llevarla a producción.', 'Consultar un proyecto', 'contacto.html?origen=taller')
def page(file,title,description,body):
 parent = ('productos.html' if file.startswith('producto-') else 'taller.html' if file in ('proyecto-bandera.html','proyecto-letras-proceso.html','proyecto-numeracion.html') else 'proyectos.html' if file.startswith('proyecto-') else file)
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if url==file else ' aria-current="true"' if url==parent else '')+f'>{label}</a>' for url,label in nav)
 robots = 'noindex,follow' if file in ('proyecto-senalizacion.html','proyecto-exhibidor.html') else 'index,follow'
 canonical = 'https://santiagososastudio.com/' + ('' if file=='index.html' else file)
 html=f'''<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | Santiago Sosa Studio</title><meta name="description" content="{escape(description)}"><meta name="robots" content="{robots}"><link rel="canonical" href="{canonical}"><meta name="theme-color" content="#202224"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/styles.css?v=20260921-ux"><script src="assets/config.js" defer></script><script src="assets/main.js?v=20260921-ux" defer></script></head><body>
<a class="skip" href="#contenido">Saltar al contenido</a>
<header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html" aria-label="Santiago Sosa Studio, inicio">Santiago Sosa Studio<span>DISEÑO + FABRICACIÓN</span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation" hidden>Menú <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Navegación principal">{links}{button('Solicitar cotización')}</nav></div></header>
<main id="contenido">{body}</main>
<footer class="footer"><div class="wrap footer-grid"><a class="brand" href="index.html">Santiago Sosa Studio<span>DISEÑO QUE TOMA FORMA.</span></a><p>Diseño, rotulación y fabricación personalizada.<br>Bávaro–Punta Cana, República Dominicana.</p><a href="contacto.html">Contacto y cotizaciones ↗</a></div><div class="wrap footer-bottom"><span>© <span data-year>2026</span> Santiago Sosa Studio</span><span>Español · República Dominicana</span></div></footer></body></html>'''
 (root/file).write_text(html.replace('<br>', '<br> '),encoding='utf-8')
