body+='<section class="wrap section"><div class="section-heading"><div><p class="eyebrow">02 / Productos</p><h2>Piezas que puedes encargar.</h2></div><a class="text-link" href="productos.html">Ver productos ↗</a></div>'+productgrid(products[:2])+'</section>'
body+='<section class="wrap sectors sectors-compact"><h2>Diseñado para tu espacio.</h2><p>Hoteles y alojamientos · Construcción y proyectos · Restaurantes · Comercios · Oficinas</p></section>'
body+='<section class="workshop-band"><div class="wrap workshop-grid">'+photo('letras-proceso','Letras de gran formato con masilla durante la preparación y el lijado')+'<div><p class="eyebrow">04 / El taller</p><h2>Del diseño a la<br>pieza terminada.</h2><p>Diseño y fabricación de soluciones físicas, con materiales y procesos adecuados a cada proyecto.</p>'+button('Conocer el taller','taller.html',True)+'</div></div></section>'+cta()
